    serviceId: appZeropsService.id,
    publicPort: 20000,
    internalPort: 3000,
    protocol: "tcp",
    publicIpType: "IP_V6",
    firewallPolicy: "WHITELIST",
    firewallIpRanges: ["2001:db8::/32"],
    forceSync: false,
}, {
    dependsOn: [appZeropsServiceDeploy],
});
